-- Generated by scripts/bundle.mjs. Paste into the Supabase SQL editor and run once.
create table if not exists public.schema_migrations (name text primary key, applied_at timestamptz not null default now());
alter table public.schema_migrations enable row level security;

-- ===== 001_schema.sql =====
-- Core tables. Every row is reachable only through RLS (see 002).

create extension if not exists pgcrypto;

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  username text not null unique check (username ~ '^[a-z0-9_]{3,24}$'),
  display_name text not null check (char_length(display_name) between 1 and 40),
  avatar_hue int not null default floor(random() * 360),
  is_guest boolean not null default false,
  is_bot boolean not null default false,
  created_at timestamptz not null default now()
);

create table public.conversations (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('channel', 'dm')),
  slug text unique,
  name text,
  topic text check (char_length(topic) <= 140),
  is_public boolean not null default true,
  auto_join boolean not null default false,
  -- "<smaller uuid>:<larger uuid>" so a DM between two people exists once
  dm_key text unique,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  last_message_at timestamptz not null default now(),
  check (
    (kind = 'channel' and slug is not null and name is not null and dm_key is null)
    or (kind = 'dm' and dm_key is not null and slug is null and not is_public)
  )
);

create table public.members (
  conversation_id uuid not null references public.conversations (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  role text not null default 'member' check (role in ('owner', 'member')),
  joined_at timestamptz not null default now(),
  last_read_at timestamptz not null default now(),
  primary key (conversation_id, user_id)
);
create index members_user_idx on public.members (user_id);

create table public.messages (
  id bigint generated always as identity primary key,
  conversation_id uuid not null references public.conversations (id) on delete cascade,
  author_id uuid not null references public.profiles (id) on delete cascade,
  body text not null default '' check (char_length(body) <= 4000),
  attachment_path text,
  created_at timestamptz not null default now(),
  edited_at timestamptz,
  deleted_at timestamptz,
  search tsvector generated always as (to_tsvector('simple', body)) stored,
  check (deleted_at is not null or char_length(btrim(body)) > 0 or attachment_path is not null)
);
create index messages_conv_created_idx on public.messages (conversation_id, created_at desc);
create index messages_search_idx on public.messages using gin (search);

create table public.reactions (
  message_id bigint not null references public.messages (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  emoji text not null check (emoji in ('👍', '❤️', '😂', '🎉', '👀', '🔥')),
  created_at timestamptz not null default now(),
  primary key (message_id, user_id, emoji)
);

insert into public.schema_migrations (name) values ('001_schema.sql') on conflict do nothing;

-- ===== 002_security.sql =====
-- Row Level Security. Clients use the anon key plus a user session; these
-- policies are the whole authorization layer.

alter table public.profiles enable row level security;
alter table public.conversations enable row level security;
alter table public.members enable row level security;
alter table public.messages enable row level security;
alter table public.reactions enable row level security;

-- security definer so policies on members can call it without recursing
create or replace function public.is_member(conv uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from members where conversation_id = conv and user_id = auth.uid());
$$;
revoke all on function public.is_member(uuid) from public, anon;
grant execute on function public.is_member(uuid) to authenticated;

-- profiles: everyone signed in can see names; you edit only yourself
create policy profiles_read on public.profiles for select to authenticated using (true);
create policy profiles_update_own on public.profiles for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid() and not is_bot);

-- conversations: public channels are browsable, everything else is members-only.
-- Creation goes through create_channel / open_dm (003), never a direct insert.
create policy conversations_read on public.conversations for select to authenticated
  using ((kind = 'channel' and is_public) or public.is_member(id));

-- members: see the member lists of rooms you are in; join public channels; leave anything
create policy members_read on public.members for select to authenticated
  using (user_id = auth.uid() or public.is_member(conversation_id));
create policy members_join_public on public.members for insert to authenticated
  with check (
    user_id = auth.uid() and role = 'member'
    and exists (select 1 from conversations c where c.id = conversation_id and c.kind = 'channel' and c.is_public)
  );
create policy members_update_own on public.members for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy members_leave on public.members for delete to authenticated
  using (user_id = auth.uid());

-- messages: members read and write; authors edit and soft-delete their own
create policy messages_read on public.messages for select to authenticated
  using (public.is_member(conversation_id));
create policy messages_send on public.messages for insert to authenticated
  with check (author_id = auth.uid() and public.is_member(conversation_id) and edited_at is null and deleted_at is null);
create policy messages_edit_own on public.messages for update to authenticated
  using (author_id = auth.uid()) with check (author_id = auth.uid());

-- reactions: members of the message's room
create policy reactions_read on public.reactions for select to authenticated
  using (exists (select 1 from messages m where m.id = message_id and public.is_member(m.conversation_id)));
create policy reactions_add on public.reactions for insert to authenticated
  with check (user_id = auth.uid() and exists (select 1 from messages m where m.id = message_id and public.is_member(m.conversation_id)));
create policy reactions_remove on public.reactions for delete to authenticated
  using (user_id = auth.uid());

-- column-level guard: only body/edited_at/deleted_at are editable on a message
revoke update on public.messages from authenticated;
grant update (body, edited_at, deleted_at) on public.messages to authenticated;
revoke update on public.members from authenticated;
grant update (last_read_at) on public.members to authenticated;
revoke update on public.profiles from authenticated;
grant update (display_name, avatar_hue) on public.profiles to authenticated;

-- Storage: attachments/<conversation_id>/<file>, readable and writable by members
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('attachments', 'attachments', false, 5242880, array['image/png', 'image/jpeg', 'image/gif', 'image/webp'])
on conflict (id) do nothing;

create policy attachments_read on storage.objects for select to authenticated
  using (bucket_id = 'attachments' and public.is_member(((storage.foldername(name))[1])::uuid));
create policy attachments_write on storage.objects for insert to authenticated
  with check (bucket_id = 'attachments' and public.is_member(((storage.foldername(name))[1])::uuid));

-- Realtime: postgres_changes on these tables, filtered per subscriber by the RLS above
alter publication supabase_realtime add table public.messages, public.reactions;
alter table public.messages replica identity full;
alter table public.reactions replica identity full;

insert into public.schema_migrations (name) values ('002_security.sql') on conflict do nothing;

-- ===== 003_functions.sql =====
-- Signup, room creation, inbox, search, and message lifecycle triggers.

-- A profile for every auth user. Guests (anonymous sign-in) get a generated name.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  animals text[] := array['Otter','Falcon','Panda','Lynx','Koala','Heron','Fox','Orca','Ibis','Yak'];
  pick text := animals[1 + floor(random() * array_length(animals, 1))::int];
  meta jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  uname text;
begin
  uname := lower(coalesce(meta->>'username', case when new.is_anonymous then 'guest' else split_part(new.email, '@', 1) end));
  uname := left(regexp_replace(uname, '[^a-z0-9_]', '', 'g'), 17) || '_' || substr(md5(new.id::text), 1, 6);

  insert into profiles (id, username, display_name, is_guest)
  values (
    new.id,
    uname,
    coalesce(nullif(meta->>'display_name', ''), case when new.is_anonymous then 'Guest ' || pick else split_part(new.email, '@', 1) end),
    coalesce(new.is_anonymous, false)
  );

  insert into members (conversation_id, user_id)
  select id, new.id from conversations where auto_join;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Channels: slug from the name, creator becomes owner.
create or replace function public.create_channel(p_name text, p_topic text default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_slug text := trim(both '-' from regexp_replace(lower(btrim(p_name)), '[^a-z0-9]+', '-', 'g'));
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if char_length(v_slug) not between 2 and 32 then raise exception 'channel name must be 2-32 letters or numbers'; end if;

  insert into conversations (kind, slug, name, topic, created_by)
  values ('channel', v_slug, v_slug, nullif(btrim(p_topic), ''), auth.uid())
  returning id into v_id;

  insert into members (conversation_id, user_id, role) values (v_id, auth.uid(), 'owner');
  return v_id;
exception when unique_violation then
  raise exception 'a channel called #% already exists', v_slug;
end;
$$;

-- DMs are idempotent: the sorted pair is a unique key, so a race opens the same room.
create or replace function public.open_dm(p_other uuid)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_key text;
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_other = auth.uid() then raise exception 'cannot message yourself'; end if;
  if not exists (select 1 from profiles where id = p_other) then raise exception 'no such user'; end if;

  v_key := least(auth.uid(), p_other)::text || ':' || greatest(auth.uid(), p_other)::text;
  insert into conversations (kind, dm_key, is_public, created_by)
  values ('dm', v_key, false, auth.uid())
  on conflict (dm_key) do nothing;

  select id into v_id from conversations where dm_key = v_key;
  insert into members (conversation_id, user_id)
  values (v_id, auth.uid()), (v_id, p_other)
  on conflict do nothing;
  return v_id;
end;
$$;

-- Sidebar in one round trip: rooms I am in, last message, unread count.
-- security invoker, so RLS still applies to everything it reads.
create or replace function public.inbox()
returns table (
  id uuid, kind text, name text, topic text, peer_id uuid,
  last_message_at timestamptz, last_body text, last_author text, unread int
) language sql stable security invoker set search_path = public as $$
  select
    c.id, c.kind,
    coalesce(c.name, p.display_name) as name,
    c.topic,
    p.id as peer_id,
    c.last_message_at,
    lm.body, la.display_name,
    (select count(*)::int from messages m
      where m.conversation_id = c.id and m.created_at > me.last_read_at
        and m.author_id <> auth.uid() and m.deleted_at is null) as unread
  from members me
  join conversations c on c.id = me.conversation_id
  left join lateral (
    select mm.user_id from members mm
    where c.kind = 'dm' and mm.conversation_id = c.id and mm.user_id <> auth.uid() limit 1
  ) peer on true
  left join profiles p on p.id = peer.user_id
  left join lateral (
    select m.body, m.author_id from messages m
    where m.conversation_id = c.id and m.deleted_at is null
    order by m.created_at desc limit 1
  ) lm on true
  left join profiles la on la.id = lm.author_id
  where me.user_id = auth.uid()
  order by c.last_message_at desc;
$$;

-- Full-text search across every room the caller can read (RLS filters the rest).
create or replace function public.search_messages(q text)
returns table (id bigint, conversation_id uuid, body text, author text, created_at timestamptz, rank real)
language sql stable security invoker set search_path = public as $$
  select m.id, m.conversation_id, m.body, p.display_name, m.created_at,
         ts_rank(m.search, websearch_to_tsquery('simple', q)) as rank
  from messages m join profiles p on p.id = m.author_id
  where m.deleted_at is null and m.search @@ websearch_to_tsquery('simple', q)
  order by rank desc, m.created_at desc
  limit 30;
$$;

-- Spam guard for a public demo: max 8 messages per 10 seconds per user.
create or replace function public.guard_message_rate()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (select is_bot from profiles where id = new.author_id) then return new; end if;
  if (select count(*) from messages
      where author_id = new.author_id and created_at > now() - interval '10 seconds') >= 8 then
    raise exception 'slow down: too many messages' using errcode = 'P0429';
  end if;
  return new;
end;
$$;
create trigger messages_rate before insert on public.messages
  for each row execute function public.guard_message_rate();

create or replace function public.touch_conversation()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update conversations set last_message_at = new.created_at where id = new.conversation_id;
  update members set last_read_at = new.created_at
    where conversation_id = new.conversation_id and user_id = new.author_id;
  return new;
end;
$$;
create trigger messages_touch after insert on public.messages
  for each row execute function public.touch_conversation();

-- Edits stamp edited_at; deletes are soft and clear the content.
create or replace function public.message_update()
returns trigger language plpgsql as $$
begin
  if new.deleted_at is not null and old.deleted_at is null then
    new.body := '';
    new.attachment_path := null;
  elsif new.body is distinct from old.body then
    new.edited_at := now();
  end if;
  return new;
end;
$$;
create trigger messages_update before update on public.messages
  for each row execute function public.message_update();

grant execute on function public.create_channel(text, text), public.open_dm(uuid),
  public.inbox(), public.search_messages(text) to authenticated;
revoke execute on function public.create_channel(text, text), public.open_dm(uuid),
  public.inbox(), public.search_messages(text) from anon;

insert into public.schema_migrations (name) values ('003_functions.sql') on conflict do nothing;

-- ===== 004_buzzbot.sql =====
-- BuzzBot: a Postgres trigger that answers DMs, so someone testing alone
-- still gets a conversation. No server, no function host.

create or replace function public.buzzbot_answer(q text)
returns text language sql immutable as $$
  select case
    when q ~* '\m(hi|hey|hello|yo|namaste)\M' then
      'Hey! I''m BuzzBot. Open BuzzBell in a second tab or a private window as another guest and message yourself: typing, presence and messages all arrive live.'
    when q ~* '(stack|built|how|tech|work)' then
      'React + TypeScript up front. Underneath it''s Supabase: Postgres with Row Level Security, Realtime for messages, Presence for who''s online, Broadcast for typing. I''m a Postgres trigger, by the way.'
    when q ~* '(rls|secur|safe|private|policy)' then
      'Every read and write is checked by Postgres RLS policies. Even with the public key in the browser, you can only read rooms you''re a member of. The repo has tests that try to break that.'
    when q ~* '(search|find)' then
      'Try the search bar: it''s Postgres full-text search, and it only returns messages you''re allowed to read.'
    when q ~* '(who|made|author|pradumya)' then
      'Pradumya Gaurav built me. He''s a backend engineer who automates ops work with Node.js, queues and LLMs. github.com/pradumya004'
    else
      (array[
        'Noted. Try reacting to a message, or ask me how this was built.',
        'I only know a few tricks: ask me about the stack, security or search.',
        'Fun fact: this reply came from a trigger in the same transaction as your message.'
      ])[1 + floor(random() * 3)::int]
  end;
$$;

create or replace function public.buzzbot_reply()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_bot uuid;
begin
  select p.id into v_bot
  from members mm join profiles p on p.id = mm.user_id
  where mm.conversation_id = new.conversation_id and p.is_bot and p.id <> new.author_id
  limit 1;

  if v_bot is null
     or (select kind from conversations where id = new.conversation_id) <> 'dm'
     or (select is_bot from profiles where id = new.author_id) then
    return new;
  end if;

  insert into messages (conversation_id, author_id, body)
  values (new.conversation_id, v_bot, buzzbot_answer(new.body));
  return new;
end;
$$;

create trigger messages_buzzbot after insert on public.messages
  for each row execute function public.buzzbot_reply();

-- Every new person gets a DM from BuzzBot, so the inbox is never empty.
create or replace function public.buzzbot_welcome()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_bot uuid;
  v_conv uuid;
begin
  if new.is_bot then return new; end if;
  select id into v_bot from profiles where is_bot limit 1;
  if v_bot is null then return new; end if;

  insert into conversations (kind, dm_key, is_public, created_by)
  values ('dm', least(v_bot, new.id)::text || ':' || greatest(v_bot, new.id)::text, false, v_bot)
  returning id into v_conv;
  insert into members (conversation_id, user_id) values (v_conv, v_bot), (v_conv, new.id);
  insert into messages (conversation_id, author_id, body)
  values (v_conv, v_bot, 'Welcome to BuzzBell, ' || new.display_name || '! Say hi to me here, or jump into #general.');
  return new;
end;
$$;

create trigger profiles_welcome after insert on public.profiles
  for each row execute function public.buzzbot_welcome();

insert into public.schema_migrations (name) values ('004_buzzbot.sql') on conflict do nothing;

-- ===== 005_guest_names.sql =====
-- Guest names from 20 adjectives x 20 animals (400 combinations) instead of
-- 10 animals, so two guests online at once rarely share a name.

create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  adjectives text[] := array['Calm','Swift','Bright','Quiet','Bold','Lucky','Sunny','Brave','Clever','Gentle',
                             'Rapid','Witty','Mellow','Nimble','Steady','Vivid','Cosmic','Jolly','Keen','Noble'];
  animals text[] := array['Otter','Falcon','Panda','Lynx','Koala','Heron','Fox','Orca','Ibis','Yak',
                          'Badger','Crane','Gecko','Marten','Puffin','Quokka','Raven','Seal','Tapir','Wren'];
  pick text := adjectives[1 + floor(random() * 20)::int] || ' ' || animals[1 + floor(random() * 20)::int];
  meta jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  uname text;
begin
  uname := lower(coalesce(meta->>'username', case when new.is_anonymous then 'guest' else split_part(new.email, '@', 1) end));
  uname := left(regexp_replace(uname, '[^a-z0-9_]', '', 'g'), 17) || '_' || substr(md5(new.id::text), 1, 6);

  insert into profiles (id, username, display_name, is_guest)
  values (
    new.id,
    uname,
    coalesce(nullif(meta->>'display_name', ''), case when new.is_anonymous then pick else split_part(new.email, '@', 1) end),
    coalesce(new.is_anonymous, false)
  );

  insert into members (conversation_id, user_id)
  select id, new.id from conversations where auto_join;
  return new;
end;
$$;

insert into public.schema_migrations (name) values ('005_guest_names.sql') on conflict do nothing;

-- ===== seed.sql =====
-- Demo data: three channels, three teammates, BuzzBot. Safe to re-run.
-- Seeded users get a random password nobody knows, so they can't be signed into.

create or replace function pg_temp.seed_user(p_id uuid, p_email text, p_username text, p_name text, p_hue int, p_bot boolean)
returns void language plpgsql as $$
begin
  insert into auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at,
                          raw_app_meta_data, raw_user_meta_data, created_at, updated_at, is_anonymous)
  values (p_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', p_email,
          crypt(gen_random_uuid()::text, gen_salt('bf')), now(),
          '{"provider":"email","providers":["email"]}', jsonb_build_object('username', p_username, 'display_name', p_name),
          now(), now(), false)
  on conflict (id) do nothing;
  update public.profiles set avatar_hue = p_hue, is_bot = p_bot where id = p_id;
end;
$$;

